questions.solution:
function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let i = 0; i < a.length; i++) difference |= a[i] ^ b[i];
  return difference === 0;
}

console.log(constantTimeEqual([1, 2, 3], [1, 2, 3]));
console.log(constantTimeEqual([1, 2, 3], [1, 2, 4]));
console.log(constantTimeEqual([9, 2, 3], [1, 2, 3]));
console.log(constantTimeEqual([1, 2], [1, 2, 3]));

