function parseStored(value) {
  const parts = value.split("$");
  if (parts.length !== 6 || parts[0] !== "scrypt") throw new Error("unknown format");
  const [algorithm, N, r, p, salt, hash] = parts;
  return { algorithm, N: Number(N), r: Number(r), p: Number(p), salt, hash };
}

console.log(JSON.stringify(parseStored("scrypt$131072$8$1$c2FsdA$aGFzaA")));
